            "answer": "সাধারণ সমাধান: sin θ = 0 হলে θ = nπ এবং cos θ = 0 হলে θ = (2n+1)π/2। এটি শিক্ষার্থীদের তাত্ত্বিক স্পষ্টতা দেয়।",
